svg.script:
(function() {
  'use strict';

  // Dados Clínicos dos 5 Alvos da Pelvimetria
  const stepsData = [
    {
      id: 1,
      aroBadge: 'ESTREITO SUPERIOR',
      aroClass: 'entrada',
      title: '1. TOQUE DO PROMONTÓRIO ÓSSEO',
      tecnica: 'Dedos indicador e médio avançam profundamente até o fundo de saco vaginal posterior buscando atingir S1.',
      criterio: 'Promontório INALCANÇÁVEL (Conjugada Diagonal > 11,5 cm)',
      criterioColor: 'var(--a12p13b-normal)',
      prognostico: 'Se o promontório não é atingido, a Conjugada Obstétrica é ≥ 10,0 cm, confirmando entrada pélvica adequada.',
      handTransform: 'translate(10, -180) rotate(-15, 200, 300)'
    },
    {
      id: 2,
      aroBadge: 'ESTREITO MÉDIO',
      aroClass: 'meio',
      title: '2. ESPINHAS ISQUIÁTICAS',
      tecnica: 'Varredura tátil nas paredes pélvicas laterais ao nível do plano de menor diâmetro (Estreito Médio).',
      criterio: 'Espinhas NÃO PROEMINENTES (Diâmetro Interespinhoso ≥ 10,5 cm)',
      criterioColor: 'var(--a12p13b-normal)',
      prognostico: 'Espinhas rombas/aplanadas evitam parada da rotação interna do polo cefálico fetal na altura de plano 0 de De Lee.',
      handTransform: 'translate(15, 0) rotate(5, 200, 300)'
    },
    {
      id: 3,
      aroBadge: 'ESTREITO MÉDIO',
      aroClass: 'meio',
      title: '3. CONCAVIDADE SACRAL',
      tecnica: 'Deslizamento da polpa dos dedos pela face anterior do sacro, avaliando a curvatura de S1 a S5.',
      criterio: 'Sacro BEM ESCAVADO (Curvatura sacral fisiológica mantida)',
      criterioColor: 'var(--a12p13b-normal)',
      prognostico: 'Sacro plano ou em rampa projeta a espinha posteriormente, reduzindo a cavidade e dificultando a descida.',
      handTransform: 'translate(80, -60) rotate(-10, 200, 300)'
    },
    {
      id: 4,
      aroBadge: 'ESTREITO INFERIOR',
      aroClass: 'saida',
      title: '4. ÂNGULO SUBPÚBICO',
      tecnica: 'Posicionamento de dois dedos abertos sob a sínfise púbica para palpação dos ramos isquiopúbicos.',
      criterio: 'Ângulo Subpúbico AMPLO (≥ 90° - Pélvis Ginecoide/Antropoide)',
      criterioColor: 'var(--a12p13b-normal)',
      prognostico: 'Ângulos agudos (< 90°, tipo androide) empurram o polo fetal para trás contra o cóccix, travando o aro de saída.',
      handTransform: 'translate(-80, 50) rotate(25, 200, 300)'
    },
    {
      id: 5,
      aroBadge: 'ESTREITO INFERIOR',
      aroClass: 'saida',
      title: '5. TUBEROSIDADES ISQUIÁTICAS',
      tecnica: 'Compressão externa com o punho fechado (Manobra de Greenhill) no pericentro entre os dois ísquios.',
      criterio: 'Punho CABE COM FOLGA (Diâmetro Bi-isquiático ≥ 8,5 cm)',
      criterioColor: 'var(--a12p13b-normal)',
      prognostico: 'Acomodação completa do punho assegura que o diâmetro transverso do estreito inferior permite o desprendimento fetal.',
      handTransform: 'translate(0, 110) rotate(40, 200, 300)'
    }
  ];

  let currentStep = 0;

  function updateStep(index) {
    if (index < 0) index = stepsData.length - 1;
    if (index >= stepsData.length) index = 0;
    currentStep = index;

    const data = stepsData[currentStep];

    // 1. Atualizar Mão do Examinador (Transformação Anatômica)
    const handGroup = document.getElementById('a12p13b-hand-group');
    if (handGroup) {
      handGroup.setAttribute('transform', data.handTransform);
    }

    // 2. Atualizar Hotspots no Palco Anatômico
    for (let i = 1; i <= 5; i++) {
      const targetEl = document.getElementById('a12p13b-target-' + i);
      const btnEl = document.getElementById('a12p13b-btn-' + i);

      if (targetEl) {
        if (i === currentStep + 1) {
          targetEl.classList.add('is-active');
          targetEl.setAttribute('aria-selected', 'true');
        } else {
          targetEl.classList.remove('is-active');
          targetEl.setAttribute('aria-selected', 'false');
        }
      }

      if (btnEl) {
        if (i === currentStep + 1) {
          btnEl.classList.add('is-active');
        } else {
          btnEl.classList.remove('is-active');
        }
      }
    }

    // 3. Atualizar Painel de Leitura Clínica
    const badgeBg = document.getElementById('a12p13b-badge-bg');
    const badgeText = document.getElementById('a12p13b-badge-text');
    const cardTitle = document.getElementById('a12p13b-card-title');
    const infoTecnica = document.getElementById('a12p13b-info-tecnica');
    const infoCriterio = document.getElementById('a12p13b-info-criterio');
    const infoPrognostico = document.getElementById('a12p13b-info-prognostico');

    if (badgeBg && badgeText) {
      badgeBg.setAttribute('class', 'a12p13b-badge-' + data.aroClass);
      badgeText.setAttribute('class', 'a12p13b-badge-text-' + data.aroClass);
      badgeText.textContent = data.aroBadge;
    }

    if (cardTitle) cardTitle.textContent = data.title;
    if (infoTecnica) infoTecnica.textContent = data.tecnica;

    if (infoCriterio) {
      infoCriterio.textContent = data.criterio;
      infoCriterio.setAttribute('fill', data.criterioColor);
    }

    if (infoPrognostico) infoPrognostico.textContent = data.prognostico;

    // 4. Destaque no Inset Frontal quando nos Passos 4 ou 5
    const archPath = document.getElementById('a12p13b-arch-angle-path');
    const lineBi = document.getElementById('a12p13b-line-biisquiatico');
    const fistGroup = document.getElementById('a12p13b-greenhill-fist');

    if (archPath) archPath.setAttribute('stroke-width', currentStep === 3 ? '4' : '3');
    if (lineBi) lineBi.setAttribute('stroke-width', currentStep === 4 ? '3' : '2');
    if (fistGroup) fistGroup.setAttribute('opacity', currentStep === 4 ? '1.0' : '0.4');
  }

  // Event Listeners nos Alvos Anatômicos
  for (let i = 1; i <= 5; i++) {
    (function(stepIndex) {
      const target = document.getElementById('a12p13b-target-' + stepIndex);
      const btn = document.getElementById('a12p13b-btn-' + stepIndex);

      if (target) {
        target.addEventListener('click', function() { updateStep(stepIndex - 1); });
        target.addEventListener('keydown', function(e) {
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            updateStep(stepIndex - 1);
          }
        });
      }

      if (btn) {
        btn.addEventListener('click', function() { updateStep(stepIndex - 1); });
        btn.addEventListener('keydown', function(e) {
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            updateStep(stepIndex - 1);
          }
        });
      }
    })(i);
  }

  // Botões de Navegação Próximo/Anterior
  const prevBtn = document.getElementById('a12p13b-nav-prev');
  const nextBtn = document.getElementById('a12p13b-nav-next');

  if (prevBtn) {
    prevBtn.addEventListener('click', function() { updateStep(currentStep - 1); });
    prevBtn.addEventListener('keydown', function(e) {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); updateStep(currentStep - 1); }
    });
  }

  if (nextBtn) {
    nextBtn.addEventListener('click', function() { updateStep(currentStep + 1); });
    nextBtn.addEventListener('keydown', function(e) {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); updateStep(currentStep + 1); }
    });
  }

  // Suporte Global de Teclado (Setas Esquerda/Direita e Números 1-5)
  const svgRoot = document.getElementById('a12p13b-svg');
  if (svgRoot) {
    window.addEventListener('keydown', function(e) {
      if (e.key === 'ArrowRight' || e.key === 'ArrowDown') {
        updateStep(currentStep + 1);
      } else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') {
        updateStep(currentStep - 1);
      } else if (e.key >= '1' && e.key <= '5') {
        updateStep(parseInt(e.key, 10) - 1);
      }
    });
  }

  // Inicialização no Passo 1
  updateStep(0);
})();
